// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  Img,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type SelectionAnimationProps = Record<string, any>;

const SelectionAnimation: React.FC<SelectionAnimationProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 8,
  images = [
    "https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1583337130417-3346a1be7dee?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1555685812-4b943f1cb0eb?q=80&w=800&auto=format&fit=crop",
  ],
  winnerIndex = 1,
  winnerText = "WINNER!",
  highlightColor = "#fbbf24",
  cardBackgroundColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Ensure we have exactly 3 images even if array is malformed
  const safeImages = images.slice(0, 3);
  while (safeImages.length < 3) {
    safeImages.push(images[0] || "https://images.unsplash.com/photo-1579546929518-9e396f3cc809?q=80&w=800&auto=format&fit=crop");
  }

  // Animation Timings
  const startRoulette = 45;
  const revealStart = 140;
  
  // Easing jump durations: starts very fast, gradually slows down
  const jumpDurations = [3, 3, 3, 4, 4, 5, 6, 7, 9, 12, 15, 20];
  const totalJumps = jumpDurations.length;

  const getCardState = (i: number) => {
    // 1. Intro Animation
    const introProgress = spring({
      fps,
      frame: frame - i * 8,
      config: { damping: 12, mass: 0.8 },
    });

    // 2. Roulette Highlighting
    let rouletteScale = 0;
    let highlightProgress = 0;
    let currentStart = startRoulette;

    for (let j = 0; j < totalJumps; j++) {
      const jumpDur = jumpDurations[j];
      const startFrame = currentStart;
      const endFrame = startFrame + jumpDur;
      
      // Advance timeline for the next jump in the loop
      currentStart = endFrame;

      // Calculate which card is active so the final jump lands perfectly on winnerIndex
      const activeIndex = (winnerIndex - ((totalJumps - 1) - j) + 30) % 3;
      
      if (activeIndex === i) {
        if (frame >= startFrame && frame < endFrame) {
          if (j === totalJumps - 1) {
            // Final jump, stays highlighted with a strong pop
            highlightProgress = interpolate(
              frame,
              [startFrame, startFrame + 4],
              [0, 1],
              { extrapolateRight: "clamp" }
            );
            rouletteScale = interpolate(
              frame,
              [startFrame, startFrame + 4],
              [0, 0.15],
              { extrapolateRight: "clamp" }
            );
          } else {
            // Passing jump, pulses up and down. 
            // Scale bounce is smaller when moving very fast to avoid aggressive flickering.
            const midFrame = startFrame + jumpDur / 2;
            const peakScale = interpolate(jumpDur, [3, 15], [0.05, 0.15], { 
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp" 
            });

            highlightProgress = interpolate(
              frame,
              [startFrame, midFrame, endFrame],
              [0, 1, 0],
              { extrapolateRight: "clamp" }
            );
            rouletteScale = interpolate(
              frame,
              [startFrame, midFrame, endFrame],
              [0, peakScale, 0],
              { extrapolateRight: "clamp" }
            );
          }
        } else if (j === totalJumps - 1 && frame >= endFrame) {
          // Maintain final jump state permanently
          highlightProgress = 1;
          rouletteScale = 0.15;
        }
      }
    }

    // 3. Winner Reveal
    const isWinner = i === winnerIndex;
    let finalScale = introProgress + rouletteScale;
    let finalOpacity = interpolate(introProgress, [0, 1], [0, 1]);
    
    // Layout positions
    const spacing = width * 0.28;
    let finalTranslateX = (i - 1) * spacing;
    let finalTranslateY = interpolate(introProgress, [0, 1], [150, 0]);

    if (frame >= revealStart) {
      if (isWinner) {
        const moveProgress = spring({
          fps,
          frame: frame - revealStart,
          config: { damping: 14, mass: 0.9 },
        });
        finalTranslateX = interpolate(
          moveProgress,
          [0, 1],
          [(i - 1) * spacing, 0]
        );
        finalScale = interpolate(moveProgress, [0, 1], [1.15, 1.5]);
      } else {
        const fadeOut = interpolate(
          frame,
          [revealStart, revealStart + 15],
          [1, 0],
          { extrapolateRight: "clamp" }
        );
        finalOpacity = fadeOut;
        finalScale = interpolate(
          frame,
          [revealStart, revealStart + 15],
          [1, 0.8],
          { extrapolateRight: "clamp" }
        );
      }
    }

    return {
      scale: Math.max(0, finalScale),
      opacity: finalOpacity,
      translateX: finalTranslateX,
      translateY: finalTranslateY,
      highlightProgress,
    };
  };

  // Winner Text Animation
  const textSpring = spring({
    fps,
    frame: frame - (revealStart + 15),
    config: { damping: 12 },
  });
  
  const textOpacity = interpolate(textSpring, [0, 1], [0, 1]);
  const textScale = interpolate(textSpring, [0, 1], [0.5, 1]);
  const textTranslateY = interpolate(textSpring, [0, 1], [40, 0]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
      }}
    >
      {/* Cards Container */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 0,
          height: 0,
        }}
      >
        {safeImages.map((src, i) => {
          const { scale, opacity, translateX, translateY, highlightProgress } =
            getCardState(i);
            
          const cardWidth = 460;
          const cardHeight = 460;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                width: cardWidth,
                height: cardHeight,
                marginLeft: -cardWidth / 2,
                marginTop: -cardHeight / 2,
                transform: `translate(${translateX}px, ${translateY}px) scale(${scale})`,
                opacity: opacity,
                backgroundColor: cardBackgroundColor,
                borderRadius: 24,
                boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.15)",
                zIndex: i === winnerIndex && frame >= revealStart ? 10 : 1,
              }}
            >
              {/* Image element */}
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  borderRadius: 24,
                  overflow: "hidden",
                  position: "relative",
                  zIndex: 2,
                }}
              >
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
              </div>

              {/* Highlight Glow Overlay */}
              <AbsoluteFill
                style={{
                  borderRadius: 24,
                  border: `8px solid ${highlightColor}`,
                  boxShadow: `inset 0 0 20px ${highlightColor}, 0 0 40px ${highlightColor}`,
                  opacity: highlightProgress,
                  zIndex: 3,
                  boxSizing: "border-box",
                  pointerEvents: "none",
                }}
              />
            </div>
          );
        })}
      </div>

      {/* Winner Reveal Text */}
      <div
        style={{
          position: "absolute",
          top: "12%",
          left: "50%",
          transform: `translate(-50%, 0) translateY(${textTranslateY}px) scale(${textScale})`,
          opacity: textOpacity,
          zIndex: 20,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
        }}
      >
        <div
          style={{
            backgroundColor: highlightColor,
            padding: "16px 48px",
            borderRadius: 100,
            boxShadow: "0 20px 25px -5px rgba(0, 0, 0, 0.1)",
          }}
        >
          <span
            style={{
              color: "#000000",
              fontSize: 64,
              fontWeight: 900,
              textTransform: "uppercase",
              letterSpacing: "0.05em",
              margin: 0,
              lineHeight: 1,
            }}
          >
            {winnerText}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SelectionAnimation;